"""Temporary hash-locked transport; source and tests survive, payload does not."""
import base64
import hashlib
import subprocess
import zlib
from pathlib import Path
root = Path(__file__).resolve().parents[1]
p = root / 'src/decompiled/6kinoko_rebuilt.c'
assert hashlib.sha256(p.read_bytes()).hexdigest() == '831315880b2385de2d84819564a76068497c540cafc1d7e7a5e9d3eadf1ee9f7'
patch = zlib.decompress(base64.b64decode(''''''))
assert hashlib.sha256(patch).hexdigest() == 'e5c3a7425bfa1fe71772809f3517408788641cbd28f35567274bb3cc1a01c25c'
subprocess.run(['git','apply','--check','--whitespace=nowarn','-'],input=patch,cwd=root,check=True)
subprocess.run(['git','apply','--whitespace=nowarn','-'],input=patch,cwd=root,check=True)
assert hashlib.sha256(p.read_bytes()).hexdigest() == '054256e300192c646e3ad5eab850111f149570324d8f683ae9558060965e403a'
Path(__file__).unlink()
